import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Navbar from './components/Navbar';
import HomePage from './pages/HomePage';
import ProductListPage from './pages/ProductListPage';
import ProductDetailPage from './pages/ProductDetailPage';
import CartPage from './pages/CartPage';
import CheckoutPage from './pages/CheckoutPage';
import LoginPage from './pages/LoginPage';
import OrdersPage from './pages/OrdersPage';
import { getOrders, loginUser } from './services/api';

function App() {
    // State management
    const [cart, setCart] = useState([]);
    const [user, setUser] = useState(null);
    const [orders, setOrders] = useState([]);
    const [isLoading, setIsLoading] = useState(false);

    // Handle user login
    const handleLogin = async (email, password) => {
        try {
            const userData = await loginUser(email, password); // Login API call
            setUser(userData); // Set user in state
            localStorage.setItem('token', userData.token); // Save token to localStorage
        } catch (error) {
            console.error('Error logging in:', error.message);
        }
    };

    // Handle user logout
    const handleLogout = () => {
        setUser(null);
        setCart([]); // Clear the cart on logout
        localStorage.removeItem('token'); // Remove token from localStorage
    };

    // Fetch orders for the logged-in user
    useEffect(() => {
        const fetchUserOrders = async () => {
            if (user) {
                setIsLoading(true);
                try {
                    const fetchedOrders = await getOrders(); // Fetch orders API call
                    setOrders(fetchedOrders);
                } catch (error) {
                    console.error('Error fetching orders:', error.message);
                } finally {
                    setIsLoading(false);
                }
            }
        };

        fetchUserOrders();
    }, [user]);

    // Clear the cart
    const handleClearCart = () => {
        setCart([]); // Reset the cart state
        console.log('Cart cleared successfully.'); // Debug log
    };

    return (
        <Router>
            <Navbar
                user={user}
                onLogout={handleLogout}
                cartCount={cart.length} // Pass cart count to Navbar
            />
            <Routes>
                <Route path="/" element={<HomePage />} />
                <Route path="/products" element={<ProductListPage />} />
                <Route path="/products/:id" element={<ProductDetailPage />} />
                <Route
                    path="/cart"
                    element={<CartPage cart={cart} onClearCart={handleClearCart} />}
                />
                <Route
                    path="/checkout"
                    element={
                        user ? (
                            <CheckoutPage cart={cart} onClearCart={handleClearCart} />
                        ) : (
                            <Navigate to="/login" />
                        )
                    }
                />
                <Route
                    path="/login"
                    element={
                        user ? <Navigate to="/" /> : <LoginPage onLogin={handleLogin} />
                    }
                />
                <Route
                    path="/orders"
                    element={
                        user ? (
                            <OrdersPage orders={orders} isLoading={isLoading} />
                        ) : (
                            <Navigate to="/login" />
                        )
                    }
                />
            </Routes>
        </Router>
    );
}

export default App;
